const iconPaths={pen:'M4 20h4L20 8l-4-4L4 16v4M14 6l4 4M4 4h6M4 8h3',chart:'M4 4v16h16M8 15v-4M12 15V7M16 15v-6',calendar:'M5 5h14v15H5zM8 3v4M16 3v4M5 10h14M9 14h2M14 14h2',search:'M15 15l5 5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',box:'M3 7l9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10M7 5l9 4',chat:'M4 4h16v12H9l-5 4zM8 8h8M8 12h5',file:'M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6',gear:'M12 3v3M12 18v3M3 12h3M18 12h3M5 5l3 3M16 16l3 3M5 19l3-3M16 8l3-3M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',people:'M10 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0M2 20v-3a5 5 0 0 1 10 0v3M15 5a3 3 0 0 1 0 6M15 14a5 5 0 0 1 6 5',trend:'M3 17l6-6 4 3 8-10M15 4h6v6'};
const iconTypes=['pen','chart','calendar','search','pen','box','file','chart','chart','chat','chart','box','chat','people','search','box','box','chart','calendar','gear','search','file','people','people','file','chart','search'];
function axIcon(type){return `<span class="agent-glyph" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[type]||iconPaths.file}"/></svg></span>`}
const simulator=document.createElement('section');simulator.id='business-simulator';$('#metrics').before(simulator);
const simState={promotion:12,newmix:15,discount:-2};
function scenarioData(){const c=$('#analysisChannel').value;$('#analysisChannel').value='online';const on=values();$('#analysisChannel').value='offline';const off=values();$('#analysisChannel').value=c;const rows=[['온라인',on,1],['오프라인',off,.35]].map(([name,data,exposure])=>{const b=data.current,volume=1+simState.promotion/100*.7*exposure+simState.newmix/100*.45;const price=1-simState.discount/100;const revenue=b[0]*volume*price;const cost=b[1]*volume*(1+simState.newmix/100*.08);const expenses=b[2]+b[0]*Math.max(0,simState.promotion)/100*.12*exposure;return{name,base:b[0],revenue,cost,expenses,gross:revenue-cost,profit:revenue-cost-expenses,lastYear:data.lastYear[0],lastMonth:data.lastMonth[0],target:data.target[0]}});const total={name:'전체'};for(const k of ['base','revenue','cost','expenses','gross','profit','lastYear','lastMonth','target'])total[k]=rows.reduce((s,r)=>s+r[k],0);return [total,...rows]}
function drawSimulator(){simulator.innerHTML=`<div class="sim-heading"><div><span class="kicker">BUSINESS INTELLIGENCE</span><h2>${analysisType==='plan'?'매출계획':'손익분석'} — 숫자에서 다음 행동으로</h2></div><span class="demo">100% 가상 데이터 · 가정 시뮬레이션</span></div><div class="sim-layout"><article class="sim-controls"><div class="section-head"><h3>가정에 따른 다음 달 ${analysisType==='plan'?'매출계획':'손익'} 시뮬레이터</h3><button id="resetScenario">초기화</button></div>${[['promotion','온라인·플랫폼 프로모션 비중 확대',0,40,'%'],['newmix','신상품 물량 비중',0,40,'%'],['discount','평균 할인율 조정 (마진 영향)',-10,10,'%p']].map(([k,n,min,max,unit])=>`<label class="slider-label" for="sim-${k}"><span>${n}</span><output id="out-${k}"></output></label><input type="range" id="sim-${k}" min="${min}" max="${max}" step="1" value="${simState[k]}" aria-label="${n}">`).join('')}<div class="sim-kpis" id="simKpis"></div></article><div class="sim-results"><article class="analyst-comment"><span class="comment-label">AI ANALYST COMMENT</span><b>시뮬레이션 권고안 · 규칙 기반</b><p id="scenarioComment"></p></article><div class="table-wrap"><table class="scenario-table"><thead><tr><th>부문 (가상)</th><th>기준월 매출</th><th>다음 달 매출 가정</th><th>권고 액션</th></tr></thead><tbody id="scenarioRows"></tbody></table></div></div></div><div id="scenarioComparisons"></div><details class="definitions"><summary>가정과 계산식 확인</summary><p>물량 계수 = 1 + 프로모션 변화 × 0.7 × 채널 민감도 + 신상품 비중 변화 × 0.45. 채널 민감도는 온라인 1, 오프라인 0.35입니다. 매출 = 기준월 매출 × 물량 계수 × (1 − 할인율 변화). 원가 = 기준월 원가 × 물량 계수 × (1 + 신상품 비중 변화 × 0.08). 판관비 = 기준월 판관비 + 기준월 매출 × 프로모션 변화 × 0.12 × 채널 민감도.</p><p>전체는 온라인+오프라인 합계입니다. 글로벌은 이 시뮬레이터에서 제외합니다. 비중 변화는 독립적인 가상 가정이며 점유율 합계가 아닙니다. 할인율 -2%p는 기준 판매가 대비 2% 상승으로 단순화합니다. 계수는 설명용 가정으로, 실제 수요예측·회계 분석 모델이 아닙니다. 전년·전월·목표 수치는 기존 데모 기준과 비교하며 다음 달 확정 목표가 아닙니다.</p></details>`;['promotion','newmix','discount'].forEach(k=>$('#sim-'+k).oninput=e=>{simState[k]=Number(e.target.value);updateScenario()});$('#resetScenario').onclick=()=>{Object.assign(simState,{promotion:12,newmix:15,discount:-2});drawSimulator()};updateScenario()}
function updateScenario(){const rows=scenarioData();const selected=$('#analysisChannel').value;const r=selected==='online'?rows[1]:selected==='offline'?rows[2]:rows[0];for(const k of ['promotion','newmix','discount'])$('#out-'+k).textContent=signed(simState[k])+(k==='discount'?'%p':'%');const margin=r.gross/r.revenue*100;$('#simKpis').innerHTML=[['예상 월 매출',fmt(r.revenue/100,2)+'억 원'],['예상 매출총이익률',fmt(margin,1)+'%'],['예상 영업이익',fmt(r.profit/100,2)+'억 원'],['예상 영업이익률',fmt(r.profit/r.revenue*100,1)+'%']].map(([n,v])=>`<div><span>${n} (가상)</span><strong>${v}</strong></div>`).join('');$('#scenarioComment').textContent=`${r.name} 기준, 프로모션 ${signed(simState.promotion)}%와 신상품 물량 비중 ${signed(simState.newmix)}%, 할인율 ${signed(simState.discount)}%p 가정 시 매출 ${fmt(r.revenue/100,2)}억 원, 매출총이익률 ${fmt(margin)}%, 영업이익 ${fmt(r.profit/100,2)}억 원입니다. ${simState.discount>0?'할인 확대에 따른 원가·수수료 부담과 증분 이익을 확인하세요.':'가격 방어와 물량 확대의 실현 가능성, 재고 및 노출 여력을 확인하세요.'}`;const max=Math.max(...rows.map(r=>r.revenue));$('#scenarioRows').innerHTML=rows.map((x,i)=>`<tr class="${x===r?'focused':''}"><th>${x.name}</th><td>${fmt(x.base/100,2)}억</td><td><b>${fmt(x.revenue/100,2)}억</b><div class="scenario-bar"><span style="width:${x.revenue/max*100}%"></span></div></td><td>${i===0?`기준월 대비 ${delta(x.revenue,x.base,'원')} · 공급 여력과 수익성 점검`:i===1?(simState.promotion>=20?'프로모션 확대 전 광고비·수수료 회수 가능성 검토':'상품 노출과 상세페이지 전환 개선 검토'):(simState.newmix>=20?'신상품 입고·진열 일정과 매장 교육 확인':'베스트 상품 결품 방지와 재고 재배치 검토')}</td></tr>`).join('');$('#scenarioComparisons').innerHTML=`<div class="scenario-summary"><span>선택 범위: ${safe(productNames[$('#analysisProduct').value])} / ${r.name}</span><span>가상 원가 ${fmt(r.cost/100,2)}억 · 판관비 ${fmt(r.expenses/100,2)}억</span><span>전년 기준 대비 <b>${delta(r.revenue,r.lastYear,'원')}</b></span><span>전월 기준 대비 <b>${delta(r.revenue,r.lastMonth,'원')}</b></span><span>목표 기준 대비 <b>${delta(r.revenue,r.target,'원')}</b></span></div>`}
// v7: focused guide, sales targets and compact roadmap.
delete analysisNames.profit;
const guideVisuals=[['chart','필요한 만큼 사용하고, 비용은 확인하세요','질문·문서 → AI 처리 → 답변','사용 범위 줄이기 · 한도 확인'],['search','업무에 필요한 정보만 안전하게 사용하세요','권한 확인 → 최소 정보 → 출처 확인','민감정보 보호 · 접근 권한 유지'],['box','좋은 활용법을 우리 팀의 자산으로 남기세요','발견 → 기록 → 공유 → 개선','프롬프트·검토 기준·담당자 기록'],['people','최종 판단과 실행 승인은 사람이 합니다','AI 초안 → 사람 검토 → 승인 → 실행','수치·근거 검증 · 승인 이력 기록']];
document.querySelectorAll('.guide-grid article').forEach((card,i)=>{const [icon,headline,flow,tag]=guideVisuals[i];const original=[...card.children].filter(e=>e.tagName!=='H3');const visual=document.createElement('div');visual.className='guide-visual';visual.innerHTML=axIcon(icon)+`<strong>${headline}</strong><div class="guide-flow">${flow}</div><span>${tag}</span>`;card.querySelector('h3').after(visual);const details=document.createElement('details');details.className='guide-detail';details.innerHTML='<summary>실무 체크리스트 보기</summary>';original.forEach(el=>details.append(el));card.append(details)});
const targetInputs={};
const targetMoney=n=>fmt(n,2);
const targetSigned=n=>(n>0?"+":"")+fmt(n,2);
function targetKey(){return [$('#analysisMonth').value,$('#analysisProduct').value,$('#analysisChannel').value].join(':')}
const previousDrawSimulator=drawSimulator;
drawSimulator=function(){previousDrawSimulator();const channel=$('#analysisChannel').value;const channelName={all:'전체',online:'온라인',offline:'오프라인'}[channel]||'전체';const labels=[channelName+' 프로모션 비중 확대','신상품 판매 비중 확대','할인율 조정'];['promotion','newmix','discount'].forEach((key,i)=>{$(`label[for="sim-${key}"] span`).textContent=labels[i];$('#sim-'+key).setAttribute('aria-label',labels[i])});const rows=scenarioData();const row=channel==='online'?rows[1]:channel==='offline'?rows[2]:rows[0];const key=targetKey();if(!targetInputs[key])targetInputs[key]={sales:Number((row.target/100).toFixed(2)),profit:Number((row.base*.1/100).toFixed(2))};const form=document.createElement('div');form.className='target-inputs';form.innerHTML=`<h3>목표 설정 <small>단위: 억원</small></h3><label>목표매출<input id="targetSales" type="number" min="0" step="0.01" value="${targetInputs[key].sales}"></label><label>목표 영업이익<input id="targetProfit" type="number" step="0.01" value="${targetInputs[key].profit}"></label><p>초기값은 가상 예시입니다. 목표를 수정하면 달성률·차이·그래프가 즉시 바뀝니다.</p>`;$('.sim-controls').append(form);const charts=document.createElement('div');charts.id='targetCharts';$('.sim-results').append(charts);['Sales','Profit'].forEach((n,i)=>$('#target'+n).oninput=()=>{targetInputs[key][i===0?'sales':'profit']=$('#target'+n).value;updateScenario()});updateScenario()};
const previousUpdateScenario=updateScenario;
updateScenario=function(){previousUpdateScenario();const charts=$('#targetCharts');if(!charts)return;const t=targetInputs[targetKey()];if(!t)return;const rows=scenarioData(),channel=$('#analysisChannel').value,r=channel==='online'?rows[1]:channel==='offline'?rows[2]:rows[0];const valid=t.sales!==''&&t.profit!==''&&Number.isFinite(+t.sales)&&Number.isFinite(+t.profit)&&+t.sales>=0;if(!valid){charts.innerHTML='<p role="status">목표매출은 0 이상의 숫자, 목표 영업이익은 숫자로 입력해 주세요.</p>';return}charts.innerHTML=[['매출',r.revenue/100,+t.sales],['영업이익',r.profit/100,+t.profit]].map(([name,actual,target])=>{const max=Math.max(Math.abs(actual),Math.abs(target),1),negative=Math.min(actual,target)<0;return `<article class="target-chart"><h3>${name} 목표 대비 <small>억원</small></h3>${[['목표',target],['시뮬레이션',actual]].map(([label,v])=>`<div class="target-bar-row"><span>${label}</span><div class="target-track ${negative?'diverging':''}"><i style="${negative?'left:'+(v<0?50-Math.abs(v)/max*50:50)+'%;':''}width:${Math.abs(v)/max*(negative?50:100)}%;background:${v<0?'#b56565':label==='목표'?'#d7c8d1':'#a33f68'}"></i></div><b>${targetMoney(v)} </b></div>`).join('')}<p>목표 대비 차이 <strong>${targetSigned(actual-target)}억원</strong> · ${target>0?'달성률 <strong>'+fmt(actual/target*100)+'%</strong>':target===0?'목표 0: 달성률 산출 제외':'음수 목표: 달성률 대신 차이 비교'}</p>${negative?'<small>가운데 0을 기준으로 왼쪽은 음수, 오른쪽은 양수입니다.</small>':''}</article>`}).join('');const summary=$('#scenarioComparisons');summary.querySelector('span:last-child').innerHTML='입력 목표매출 대비 <b>'+(+t.sales>0?delta(r.revenue/100,+t.sales,'원'):'달성률 산출 제외')+'</b>';const comment=$('#scenarioComment');comment.textContent+=` 입력 목표매출 ${targetMoney(+t.sales)}억원 대비 ${targetSigned(r.revenue/100-Number(t.sales))}억원, 목표 영업이익 ${targetMoney(+t.profit)}억원 대비 ${targetSigned(r.profit/100-Number(t.profit))}억원입니다.`};

// Preserve the independent ERP sales board; planning uses explicitly fictional fixtures.
const priorRequestedAnalysis=drawAnalysis;
analysisNames.plan='매출계획';
drawAnalysis=function(){
 const selected=analysisType, planning=selected==='plan';
 const globalOption=$('#analysisChannel option[value=global]');
 if(globalOption){globalOption.hidden=planning;globalOption.disabled=planning;}
 if(planning&&$('#analysisChannel').value==='global')$('#analysisChannel').value='all';
 if(planning)analysisType='sales';
 priorRequestedAnalysis();analysisType=selected;
 simulator.hidden=!planning;
 if(planning){
  $('#salesDashboard').hidden=true;
  $('#insightsView > .analytics-controls').hidden=false;
  $('#exportMetrics').hidden=true;
  $('#insightsView > .section-head .demo').textContent='100% 가상 데이터 · 실제 실적 아님';
  drawSimulator();
 }
 const order=['sales','plan','logistics','customer','products'];
 $('#analyticsTabs').innerHTML=order.filter(k=>analysisNames[k]).map(k=>`<button class="${k===analysisType?'selected':''}" data-analysis="${k}">${analysisNames[k]}</button>`).join('');
 document.querySelectorAll('[data-analysis]').forEach(b=>b.onclick=()=>{analysisType=b.dataset.analysis;drawAnalysis()});
};
['analysisMonth','analysisChannel','analysisProduct'].forEach(id=>$('#'+id).onchange=drawAnalysis);
